<script setup lang="ts">import type { ApplicationError, ValidationResult } from "./types"; defineProps<{ validation: ValidationResult | null; error: ApplicationError | null }>(); const emit = defineEmits<{ jump: [path: string] }>();</script>
<template><section v-if="validation?.errors?.length || error || (validation && !validation.valid)" class="errors" role="alert"><h2>配置检查结果</h2><ul v-if="validation?.errors?.length"><li v-for="item in validation.errors" :key="`${item.fieldPath}-${item.message}`"><button v-if="item.fieldPath" type="button" @click="emit('jump', item.fieldPath)">{{ item.fieldPath }}</button><span v-else>配置</span>：{{ item.message }}</li></ul><p v-if="validation && !validation.valid">{{ validation.stage }}：{{ validation.message }}</p><p v-if="error">{{ error.stage }}：{{ error.message }} <button v-if="error.fieldPath" type="button" @click="emit('jump', error.fieldPath)">{{ error.fieldPath }}</button></p><pre v-if="validation?.stdout || validation?.stderr">{{ validation.stdout }}{{ validation.stderr }}</pre><pre v-if="error?.output">{{ error.output }}</pre></section></template>
<style scoped>.errors { margin-top:16px; padding:14px; border:1px solid color-mix(in srgb,var(--red) 40%,var(--line)); border-radius:var(--radius); color:var(--red); background:var(--red-soft); }.errors h2 { margin:0; font-size:16px; }.errors pre { overflow:auto; white-space:pre-wrap; }</style>
